commands:
/bin/zsh -lc 'set -e
inv_log="$E2E_DATA_DIR/inventory-e2e.log"
main_log="$E2E_DATA_DIR/main-e2e.log"
cd inventory-repo
PORT=3111 bun run src/server.ts >"$inv_log" 2>&1 &
inv_pid=$!
cd ../main-repo
PORT=3110 INVENTORY_URL=http://127.0.0.1:3111 bun run src/server.ts >"$main_log" 2>&1 &
main_pid=$!
cleanup() { kill "$main_pid" "$inv_pid" 2>/dev/null || true; }
trap cleanup EXIT
sleep 0.3
bun -e '"'
const inventory = \"http://127.0.0.1:3111\";
const orders = \"http://127.0.0.1:3110\";
const assert = (ok: unknown, message: string) => { if ("'!ok) throw new Error(message); };
const request = (base: string, path: string, method = "GET", body?: unknown) => fetch(base + path, { method, headers: { "content-type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
const suffix = crypto.randomUUID();
const paidSku = `paid-${suffix}`; const cancelSku = `cancel-${suffix}`; const lowSku = `low-${suffix}`;
assert((await request(inventory, "/health")).status === 200, "inventory health");
assert((await request(orders, "/health")).status === 200, "order health");
for (const [sku, quantity] of [[paidSku, 10], [cancelSku, 5], [lowSku, 1]] as const) assert((await request(inventory, "/stock", "POST", { sku, quantity })).status === 201, `seed ${sku}`);
const paidId = `paid-order-${suffix}`;
let response = await request(orders, "/orders", "POST", { id: paidId, items: [{ sku: paidSku, quantity: 3, priceCents: 137 }] });
assert(response.status === 201, "create paid order"); const created = await response.json() as any; assert(created.totalCents === 411 && created.status === "pending", "derived total");
assert((await request(orders, `/orders/${paidId}/pay`, "POST")).status === 200, "pay");
assert((await request(orders, `/orders/${paidId}/pay`, "POST")).status === 200, "duplicate pay");
assert(JSON.stringify(await (await request(inventory, `/stock/${paidSku}`)).json()) === JSON.stringify({quantity:7,reserved:0}), "paid inventory deducted once");
assert((await request(orders, `/orders/${paidId}/cancel`, "POST")).status === 409, "paid cancel rejected");
const cancelId = `cancel-order-${suffix}`;
assert((await request(orders, "/orders", "POST", { id: cancelId, items: [{ sku: cancelSku, quantity: 2, priceCents: 41 }] })).status === 201, "create cancel order");
assert((await request(orders, `/orders/${cancelId}/cancel`, "POST")).status === 200, "cancel pending");
assert(JSON.stringify(await (await request(inventory, `/stock/${cancelSku}`)).json()) === JSON.stringify({quantity:5,reserved:0}), "cancel releases");
const insufficientId = `insufficient-order-${suffix}`;
assert((await request(orders, "/orders", "POST", { id: insufficientId, items: [{ sku: cancelSku, quantity: 1, priceCents: 5 }, { sku: lowSku, quantity: 2, priceCents: 7 }] })).status === 409, "insufficient returns 409");
assert(JSON.stringify(await (await request(inventory, `/stock/${cancelSku}`)).json()) === JSON.stringify({quantity:5,reserved:0}), "atomic rollback");
console.log(JSON.stringify({ result: "pass", suffix, paid: { quantity: 7, reserved: 0 }, cancelled: { quantity: 5, reserved: 0 } }));
'"'"

