commands:
/bin/zsh -lc 'set -e
PORT=3111 bun run src/server.ts > "$E2E_DATA_DIR/inventory-live.log" 2>&1 & inventory_pid=$!
INVENTORY_URL=http://127.0.0.1:3111 PORT=3110 bun run src/server.ts > "$E2E_DATA_DIR/orders-live.log" 2>&1 & orders_pid=$!
cleanup() { kill "$orders_pid" "$inventory_pid" 2>/dev/null || true; wait "$orders_pid" "$inventory_pid" 2>/dev/null || true; }
trap cleanup EXIT
for attempt in $(seq 1 50); do
  if curl -fsS http://127.0.0.1:3111/health >/dev/null && curl -fsS http://127.0.0.1:3110/health >/dev/null; then break; fi
  sleep 0.1
done
curl -fsS http://127.0.0.1:3111/health >/dev/null
curl -fsS http://127.0.0.1:3110/health >/dev/null
bun -e '"'
const randomInt=(min,max)=>min+(crypto.getRandomValues(new Uint32Array(1))[0]%(max-min+1));
const inventory=\"http://127.0.0.1:3111\", orders=\"http://127.0.0.1:3110\", run=crypto.randomUUID();
const request=async(base,path,method=\"GET\",body)=>{const response=await fetch(base+path,{method,headers:{\"content-type\":\"application/json\"},body:body===undefined?undefined:JSON.stringify(body)});let json;try{json=await response.json()}catch{} return {response,json};};
const check=(condition,message)=>{if("'!condition)throw new Error(message)};
const equal=(actual,expected,message)=>check(JSON.stringify(actual)===JSON.stringify(expected),`${message}: ${JSON.stringify(actual)} !== ${JSON.stringify(expected)}`);
check((await request(inventory,"/health")).response.status===200,"inventory health"); check((await request(orders,"/health")).response.status===200,"orders health");
const paidSku=`paid-${run}`, paidStock=randomInt(50,150), paidQuantity=randomInt(1,paidStock-1), priceCents=randomInt(1,10000), paidOrder=`paid-${run}`;
check((await request(inventory,"/stock","POST",{sku:paidSku,quantity:paidStock})).response.status===201,"seed paid stock");
let created=await request(orders,"/orders","POST",{id:paidOrder,items:[{sku:paidSku,quantity:paidQuantity,priceCents}]}); check(created.response.status===201,"create paid order"); equal(created.json,{id:paidOrder,totalCents:paidQuantity*priceCents,status:"pending"},"derived total");
equal((await request(inventory,`/stock/${paidSku}`)).json,{quantity:paidStock,reserved:paidQuantity},"reservation visible");
check((await request(orders,`/orders/${paidOrder}/pay","POST")).response.status===200,"first payment"); check((await request(orders,`/orders/${paidOrder}/pay","POST")).response.status===200,"duplicate payment");
equal((await request(inventory,`/stock/${paidSku}`)).json,{quantity:paidStock-paidQuantity,reserved:0},"payment deducts once"); equal((await request(orders,`/orders/${paidOrder}`)).json,{id:paidOrder,items:[{sku:paidSku,quantity:paidQuantity,priceCents}],totalCents:paidQuantity*priceCents,status:"paid"},"paid order read");
const cancelSku=`cancel-${run}`, cancelStock=randomInt(10,100), cancelQuantity=randomInt(1,cancelStock), cancelOrder=`cancel-${run}`;
check((await request(inventory,"/stock","POST",{sku:cancelSku,quantity:cancelStock})).response.status===201,"seed cancel stock"); check((await request(orders,"/orders","POST",{id:cancelOrder,items:[{sku:cancelSku,quantity:cancelQuantity,priceCents:randomInt(1,10000)}]})).response.status===201,"create cancel order"); check((await request(orders,`/orders/${cancelOrder}/cancel","POST")).response.status===200,"pending cancellation"); equal((await request(inventory,`/stock/${cancelSku}`)).json,{quantity:cancelStock,reserved:0},"cancel restores reservation");
const firstSku=`first-${run}`, secondSku=`second-${run}`, firstStock=randomInt(10,100), firstQuantity=randomInt(1,firstStock), secondStock=randomInt(1,20), unavailableQuantity=secondStock+randomInt(1,20);
await request(inventory,"/stock","POST",{sku:firstSku,quantity:firstStock}); await request(inventory,"/stock","POST",{sku:secondSku,quantity:secondStock});
const insufficient=await request(orders,"/orders","POST",{id:`insufficient-${run}`,items:[{sku:firstSku,quantity:firstQuantity,priceCents:randomInt(1,10000)},{sku:secondSku,quantity:unavailableQuantity,priceCents:randomInt(1,10000)}]}); check(insufficient.response.status===409,"insufficient status"); equal((await request(inventory,`/stock/${firstSku}`)).json,{quantity:firstStock,reserved:0},"atomic release first"); equal((await request(inventory,`/stock/${secondSku}`)).json,{quantity:secondStock,reserved:0},"atomic no second reservation");
console.log(JSON.stringify({run,paidStock,paidQuantity,priceCents,cancelStock,cancelQuantity,firstStock,firstQuantity,secondStock,unavailableQuantity}));
'"'"

