const request = (base: string, path: string, method = "GET", body?: unknown) => fetch(base + path, { method, headers: { "content-type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
const suffix = crypto.randomUUID();
const paidSku = `paid-${suffix}`; const cancelSku = `cancel-${suffix}`; const lowSku = `low-${suffix}`;
assert((await request(inventory, "/health")).status === 200, "inventory health");
assert((await request(orders, "/health")).status === 200, "order health");
for (const [sku, quantity] of [[paidSku, 10], [cancelSku, 5], [lowSku, 1]] as const) assert((await request(inventory, "/stock", "POST", { sku, quantity })).status === 201, `seed ${sku}`);
