assert(JSON.stringify(await (await request(inventory, `/stock/${paidSku}`)).json()) === JSON.stringify({quantity:7,reserved:0}), "paid inventory deducted once");
assert((await request(orders, `/orders/${paidId}/cancel`, "POST")).status === 409, "paid cancel rejected");
const cancelId = `cancel-order-${suffix}`;
assert((await request(orders, "/orders", "POST", { id: cancelId, items: [{ sku: cancelSku, quantity: 2, priceCents: 41 }] })).status === 201, "create cancel order");
assert((await request(orders, `/orders/${cancelId}/cancel`, "POST")).status === 200, "cancel pending");
assert(JSON.stringify(await (await request(inventory, `/stock/${cancelSku}`)).json()) === JSON.stringify({quantity:5,reserved:0}), "cancel releases");
const insufficientId = `insufficient-order-${suffix}`;
assert((await request(orders, "/orders", "POST", { id: insufficientId, items: [{ sku: cancelSku, quantity: 1, priceCents: 5 }, { sku: lowSku, quantity: 2, priceCents: 7 }] })).status === 409, "insufficient returns 409");
assert(JSON.stringify(await (await request(inventory, `/stock/${cancelSku}`)).json()) === JSON.stringify({quantity:5,reserved:0}), "atomic rollback");
console.log(JSON.stringify({ result: "pass", suffix, paid: { quantity: 7, reserved: 0 }, cancelled: { quantity: 5, reserved: 0 } }));
'

